namespace tunuino {
struct ProjectDifference {QStringList path;QJsonValue current,source;};
inline QJsonValue projectValue(QJsonValue value,const QStringList &path){for(const auto &key:path)value=value.isArray()?value.toArray().at(key.toInt()):value.toObject().value(key);return value;}
inline QJsonValue replaceProjectValue(QJsonValue value,const QStringList &path,int at,const QJsonValue &replacement){if(at==path.size())return replacement;if(value.isArray()){auto a=value.toArray();const int i=path[at].toInt();a[i]=replaceProjectValue(a[i],path,at+1,replacement);return a;}auto o=value.toObject();o[path[at]]=replaceProjectValue(o[path[at]],path,at+1,replacement);return o;}
inline void projectDifferences(const QJsonValue &a,const QJsonValue &b,QStringList path,QVector<ProjectDifference> &out){
 if(a==b)return;if(a.isObject()&&b.isObject()){auto keys=a.toObject().keys();for(const auto &k:b.toObject().keys())if(!keys.contains(k))keys<<k;keys.sort();for(const auto &k:keys)projectDifferences(a.toObject()[k],b.toObject()[k],path+QStringList{k},out);}
 else if(a.isArray()&&b.isArray()&&a.toArray().size()==b.toArray().size()){for(int i=0;i<a.toArray().size();++i)projectDifferences(a.toArray()[i],b.toArray()[i],path+QStringList{QString::number(i)},out);}else out.append({path,a,b});
}
class ProjectComparator final:public QWidget {
public:
 explicit ProjectComparator(MapProject *project,QWidget *parent=nullptr):QWidget(parent),project_(project){setObjectName("projectComparator");auto *layout=new QVBoxLayout(this);auto *bar=SensorUi::toolbar(this);auto *open=bar->addAction(CalibrationAppearance::icon(CalibrationAppearance::Open),tr("Open comparison project..."));connect(open,&QAction::triggered,this,[this]{const auto path=QFileDialog::getOpenFileName(this,tr("Compare project"),MapProject::defaultDirectory(),tr("Tunuino project (*.tnproj)"));if(path.isEmpty())return;QString error;if(!load(path,error))QMessageBox::warning(this,tr("Project Comparator"),error);});auto *refresh=bar->addAction(style()->standardIcon(QStyle::SP_BrowserReload),tr("Compare again"));connect(refresh,&QAction::triggered,this,[this]{QString error;if(!compare(error))status_->setText(error);});auto *apply=bar->addAction(style()->standardIcon(QStyle::SP_ArrowLeft),tr("Apply selected differences locally"));apply->setObjectName("compareApply");connect(apply,&QAction::triggered,this,[this]{if(QMessageBox::question(this,tr("Project Comparator"),tr("Apply the selected differences to the local project? No ECU write will occur."),QMessageBox::Yes|QMessageBox::Cancel,QMessageBox::Cancel)!=QMessageBox::Yes)return;QString error;if(!applySelected(error))status_->setText(error);});layout->addWidget(bar);tabs_=new QTabWidget(this);tabs_->setObjectName("projectComparisonTabs");connect(tabs_,&QTabWidget::currentChanged,apply,[apply](int index){apply->setEnabled(index!=2);});layout->addWidget(tabs_,1);for(const auto &name:{tr("Variables"),tr("Tables"),tr("Stored base (read only)")}){auto *table=new QTableWidget(0,3,tabs_);table->setHorizontalHeaderLabels({tr("Parameter / cell"),tr("Current project"),tr("File project")});table->horizontalHeader()->setSectionResizeMode(QHeaderView::Stretch);table->setEditTriggers(QAbstractItemView::NoEditTriggers);table->setSelectionBehavior(QAbstractItemView::SelectRows);table->setObjectName(tables_.size()==0?"compareVariables":tables_.size()==1?"compareTables":"compareBase");tables_<<table;tabs_->addTab(table,name);table->setContextMenuPolicy(Qt::CustomContextMenu);connect(table,&QWidget::customContextMenuRequested,this,[this,table](QPoint pos){if(table==tables_[2])return;QMenu menu(this);auto *action=menu.addAction(tr("Apply selection locally"));if(menu.exec(table->viewport()->mapToGlobal(pos))==action){QString error;if(!applySelected(error))status_->setText(error);}});}status_=new QLabel(tr("Open a project to compare. Stored base pages are never imported by this tool."),this);status_->setWordWrap(true);layout->addWidget(status_);}
 bool load(const QString &path,QString &error){QFile file(path);QJsonObject source;if(!file.open(QIODevice::ReadOnly)||file.size()>2*1024*1024){error=tr("Cannot read project file.");return false;}if(!MapProject::decode(file.readAll(),source,error))return false;if(source.isEmpty())return false;auto old=source_;auto oldPath=sourcePath_;if(!source.contains("dbw"))source["dbw"]=DbwSignals::defaults();source_=source;sourcePath_=path;if(compare(error))return true;source_=old;sourcePath_=oldPath;return false;}
 bool compare(QString &error){if(source_.isEmpty()){error=tr("Open a comparison project first.");return false;}if(!project_->capture||(project_->canUse&&!project_->canUse())){error=tr("Wait for the ECU operation to finish.");return false;}auto current=project_->capture(error);if(current.isEmpty())return false;differences_.clear();projectDifferences(current,source_,{},differences_);for(auto *table:tables_)table->setRowCount(0);const auto catalog=ParameterCatalog::blocks();for(int i=0;i<differences_.size();++i){const auto &d=differences_[i];if(d.path.isEmpty())continue;const int group=d.path[0]=="tables"?1:d.path[0]=="pages"||d.path[0]=="target"?2:0;auto *table=tables_[group];const int row=table->rowCount();table->insertRow(row);QString title=d.path.join(" / ");if(d.path.size()>=4&&d.path[0]=="parameters"&&d.path[2]=="values")for(const auto &b:catalog)if(b.key==d.path[1])for(const auto &f:b.fields)if(f.key==d.path[3])title=b.title+" / "+f.label;if(d.path[0]=="service")title=tr("Project comment");
 if(d.path[0]=="tables"&&d.path.size()>=4){const QString name=d.path[1]=="fuel"?tr("Fuel Table"):d.path[1]=="ignition"?tr("Ignition Table"):d.path[1]=="vvt"?tr("VVT CAM 1 target"):tr("AFR Target");if(d.path[2]=="cells"&&d.path.size()==5){const auto tableState=current["tables"].toObject()[d.path[1]].toObject();title=tr("%1 / Cell %2,%3 — RPM %4 / MAP %5 kPa").arg(name).arg(d.path[3].toInt()+1).arg(d.path[4].toInt()+1).arg(tableState["rpm"].toArray()[d.path[4].toInt()].toDouble()).arg(tableState["load"].toArray()[d.path[3].toInt()].toDouble());}else title=name+" / "+(d.path[2]=="rpm"?tr("RPM axis"):tr("MAP axis"))+" / "+QString::number(d.path[3].toInt()+1);}
 auto *label=new QTableWidgetItem(title);label->setData(Qt::UserRole,i);table->setItem(row,0,label);for(int col=1;col<3;++col){const auto value=col==1?d.current:d.source;QString text=value.isUndefined()?tr("Absent"):value.isString()?value.toString():QString::fromUtf8(QJsonDocument(QJsonArray{value}).toJson(QJsonDocument::Compact)).mid(1);if(!value.isString()&&!value.isUndefined())text.chop(1);if(text.size()>120)text=text.left(80)+tr("… (%1 characters)").arg(text.size());table->setItem(row,col,new QTableWidgetItem(text));}}status_->setText(tr("%1 | %2 differences. Select rows in Variables or Tables to apply locally. Stored base pages remain unchanged.").arg(QFileInfo(sourcePath_).fileName()).arg(differences_.size()));return true;}
 bool applySelected(QString &error){if(tabs_->currentIndex()==2){error=tr("Stored base pages are read only.");return false;}if(!project_->capture||!project_->applyEdits||(project_->canUse&&!project_->canUse())){error=tr("Local project editing is unavailable during the current operation.");return false;}auto current=project_->capture(error);if(current.isEmpty())return false;QJsonValue desired=current;QSet<QString> cellTables;bool selected=false;for(int group=0;group<2;++group)for(const auto &range:tables_[group]->selectedRanges())for(int row=range.topRow();row<=range.bottomRow();++row){const auto &d=differences_[tables_[group]->item(row,0)->data(Qt::UserRole).toInt()];if(d.current.isUndefined()||d.source.isUndefined()){error=tr("This difference requires a complete compatible editor block.");return false;}if(projectValue(current,d.path)!=d.current){error=tr("The selected value changed since comparison. Compare again; local edits were preserved.");return false;}if(d.path.size()==5&&d.path[0]=="tables"&&d.path[2]=="cells")cellTables.insert(d.path[1]);desired=replaceProjectValue(desired,d.path,0,d.source);selected=true;}if(!selected){error=tr("Select differences in Variables or Tables first.");return false;}for(const auto &key:cellTables){const auto incoming=source_["tables"].toObject()[key].toObject(),candidate=desired.toObject()["tables"].toObject()[key].toObject();if(incoming["rpm"]!=candidate["rpm"]||incoming["load"]!=candidate["load"]){error=tr("Table axes differ. Select the corresponding axis differences together with the cells, then apply again.");return false;}}if(!project_->applyEdits(desired.toObject(),error))return false;return compare(error);}
private:MapProject *project_;QJsonObject source_;QString sourcePath_;QVector<ProjectDifference> differences_;QVector<QTableWidget*> tables_;QTabWidget *tabs_;QLabel *status_;
};
}
